-- ==========================================================================================
-- This procedure was automatically generated by Insikt Studio.
-- Any edits can and will be overwritten.
-- ==========================================================================================
create procedure [dbo].[ETL_Fact_GeneralLedger_BalanceCalc]
(
	@Type nvarchar(4000) = null
	,@ParamList nvarchar(4000) = null	
	,@ParentEventID int = null
	,@OverrideCurrentDate datetime = null
)
as
--
-- Standardvariabler
--
declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount


begin try
	--------------------------------------------------------------------------
	-- Start
	--------------------------------------------------------------------------
	exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output, @EventObject = @ProcName
			,@EventTitle = 'ETL Fact: ETL_Fact_GeneralLedger_BalanceCalc'
			,@Description = ''

	 
	
	
	--------------------------------------------------------------------------
	-- Uppdatera ingående balanser
	--------------------------------------------------------------------------		
	declare
		@CurrentFiscalYearID int
		,@LastOpeningBalanceFromSourceFiscalYearID int
		
		
	declare @CurrentDate datetime
	set @CurrentDate = isnull(@OverrideCurrentDate, getdate())
			
	select
		@CurrentFiscalYearID = t.FiscalYear	
	from
		dw.dim_Time t
	where
		t.[Year] = year(@CurrentDate)
		and t.[Month] = month(@CurrentDate)
		and t.[Day] = day(@CurrentDate)
	
	
	
	
	select
		@LastOpeningBalanceFromSourceFiscalYearID = max(t.FiscalYear)
	from
		[dw].[fact_GeneralLedger] f
			inner join dw.dim_Balanskonto b on
				b.KontoID = f.KontoID
			inner join dw.dim_Time t on
				t.DateID = f.PostingDateID
	where
		f.RowTypeID = 10 -- Ingående balans (huvudbok) - Laddad från källsystem
		-- 11 -- Ingående balans (huvudbok) - DW-genererad
	
	
	declare @LoadPeriodChangeFromFiscalYearID int
	
	if @LastOpeningBalanceFromSourceFiscalYearID is null
		select
			@LoadPeriodChangeFromFiscalYearID = min(t.FiscalYear)
		from
			[dw].[fact_GeneralLedger] f
				inner join dw.dim_Balanskonto b on
					b.KontoID = f.KontoID
				inner join dw.dim_Time t on
					t.DateID = f.PostingDateID
	else
		set @LoadPeriodChangeFromFiscalYearID = @LastOpeningBalanceFromSourceFiscalYearID
	
	
	--select
	--	@CurrentFiscalYearID  as [@CurrentFiscalYearID]
	--	,@LastOpeningBalanceFromSourceFiscalYearID as [@LastOpeningBalanceFromSourceFiscalYearID]
	--	,@LoadPeriodChangeFromFiscalYearID as [@LoadPeriodChangeFromFiscalYearID]
	
	
	
	delete from f
	from
		[dw].[fact_GeneralLedger] f
			inner join dw.dim_Time t on
				t.DateID = f.PostingDateID
	where
		f.RowTypeID = 11 -- Ingående balans (huvudbok) - DW-genererad
		and t.FiscalYear > @LoadPeriodChangeFromFiscalYearID
	
	declare 
		@FiscalYearIterator int = @LoadPeriodChangeFromFiscalYearID
		,@NextYearOpeningBalancePostingDateID int
	
	while (@FiscalYearIterator < @CurrentFiscalYearID)
		begin
			select
				@NextYearOpeningBalancePostingDateID = t.DateID
			from
				dw.dim_Time t
			where
				t.FiscalYear = @FiscalYearIterator + 1
				and t.FiscalPeriod = 1
				and t.Day = 1
	
			;with NextYearOpeningBalance as
			(
				select
					PostingDateID = @NextYearOpeningBalancePostingDateID
	
									,[KontoID] = f.[KontoID]
									,[VerifikationstypID] = f.[VerifikationstypID]
									,[LeverantörID] = f.[LeverantörID]
									,[AnläggningID] = f.[AnläggningID]
									,[KundID] = f.[KundID]
									,[AnställdID] = f.[AnställdID]
									,[KampanjID] = f.[KampanjID]
									,[VarugruppID] = f.[VarugruppID]
									,[KassaID] = f.[KassaID]
									,[ProjektID] = f.[ProjektID]
									,[AvdelningID] = f.[AvdelningID]
									,[SA_SourceSystemID] = f.[SA_SourceSystemID]
													,[Amount] = sum(f.[Amount])
									,[Number] = sum(f.[Number])
								from
					[dw].[fact_GeneralLedger] f
						inner join dw.dim_Balanskonto b on
							b.KontoID = f.KontoID
						inner join dw.dim_Time t on
							t.DateID = f.PostingDateID
				where
					t.FiscalYear = @FiscalYearIterator
					-- No RowTypeID filter -> Opening balance + period change -> Closing balance
				group by
									f.[KontoID]
									,f.[VerifikationstypID]
									,f.[LeverantörID]
									,f.[AnläggningID]
									,f.[KundID]
									,f.[AnställdID]
									,f.[KampanjID]
									,f.[VarugruppID]
									,f.[KassaID]
									,f.[ProjektID]
									,f.[AvdelningID]
									,f.[SA_SourceSystemID]
							)
			
			INSERT INTO [dw].[fact_GeneralLedger]
			(
				[PostingDateID]
				,[GLTransactionTypeID]
				,[RowTypeID]
	
							,[KontoID]
							,[VerifikationstypID]
							,[LeverantörID]
							,[AnläggningID]
							,[KundID]
							,[AnställdID]
							,[KampanjID]
							,[VarugruppID]
							,[KassaID]
							,[ProjektID]
							,[AvdelningID]
							,[Amount]
							,[Number]
							,[SA_SourceSystemID]
						)
			select
				[PostingDateID]
				
				,[GLTransactionTypeID] = 1			
				,[RowTypeID] = 11 -- Ingående balans (huvudbok) - DW-genererad
				
							,[KontoID]
							,[VerifikationstypID]
							,[LeverantörID]
							,[AnläggningID]
							,[KundID]
							,[AnställdID]
							,[KampanjID]
							,[VarugruppID]
							,[KassaID]
							,[ProjektID]
							,[AvdelningID]
							,[Amount]
							,[Number]
							,[SA_SourceSystemID]
						from
				NextYearOpeningBalance
			where
							abs([Amount]) > 0.00001
							or abs([Number]) > 0.00001
							
	
	
		
				
			set @FiscalYearIterator = @FiscalYearIterator + 1
		end

	exec app.LogEventStop @EventIDStack = @EventIDStack out
	--------------------------------------------------------------------------
	-- Stop
	--------------------------------------------------------------------------
end try
begin catch	
	--
	-- Roll back any transactions and log errors
	--
	if @TranCount = 0 and @@trancount > 0 rollback tran
	exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
	exec app.ReThrowError
end catch

GO
